import { expect, sample, test, uniqueName } from "../../fixtures";

type DocumentOut = { id: string; kind: string; status: string };
type ExtractionOut = { id: string; document_id: string; kind: string; status: string };

const PDF_BYTES = Buffer.from("%PDF-1.4\n% REV-06 synthetic document\n%%EOF\n");

test.describe("REV-06 review vendors", () => {
  test(
    "rejecting an extraction requires a note and returns the vendor to the member",
    { tag: "@REV-06" },
    async ({ apiAs }) => {
      // Arrange: a vendor in review with three extracted documents.
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");

      const created = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV06 Vendor"),
          category: "services",
          contact_email: `rev06.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@northwind.test`,
        },
      });
      expect(created.status()).toBe(201);
      const vendor = (await created.json()) as { id: string };

      const kinds = ["w9", "insurance_certificate", "contract"] as const;
      const documents: DocumentOut[] = [];
      for (const kind of kinds) {
        const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind,
            file: { name: `${kind}.pdf`, mimeType: "application/pdf", buffer: PDF_BYTES },
          },
        });
        expect(upload.status()).toBe(201);
        documents.push((await upload.json()) as DocumentOut);
      }

      // Wait for every document to finish extraction.
      for (const doc of documents) {
        let current: DocumentOut | undefined;
        for (let attempt = 0; attempt < 60; attempt++) {
          const res = await member.get(`/api/documents/${doc.id}`);
          expect(res.status()).toBe(200);
          current = (await res.json()) as DocumentOut;
          if (current.status !== "processing") break;
          await new Promise((r) => setTimeout(r, 500));
        }
        expect(current?.status).toBe("extracted");
      }

      const submitted = await member.post(`/api/vendors/${vendor.id}/submit`);
      expect(submitted.status()).toBe(200);

      // Locate the W-9 extraction.
      const w9Document = documents.find((d) => d.kind === "w9");
      expect(w9Document).toBeDefined();
      const extractionRes = await reviewer.get(`/api/documents/${w9Document!.id}/extraction`);
      expect(extractionRes.status()).toBe(200);
      const w9Extraction = (await extractionRes.json()) as ExtractionOut;
      expect(w9Extraction.status).toBe("pending_review");

      // Act & Assert: rejecting without a note is refused.
      const withoutNote = await reviewer.post(`/api/extractions/${w9Extraction.id}/decision`, {
        data: { decision: "reject" },
      });
      expect(withoutNote.status()).toBe(422);

      // Act & Assert: rejecting with a note succeeds and the vendor is rejected.
      const withNote = await reviewer.post(`/api/extractions/${w9Extraction.id}/decision`, {
        data: { decision: "reject", note: "Tax ID does not match" },
      });
      expect(withNote.status()).toBe(200);
      const rejectedExtraction = (await withNote.json()) as ExtractionOut;
      expect(rejectedExtraction.status).toBe("rejected");

      const vendorRes = await member.get(`/api/vendors/${vendor.id}`);
      expect(vendorRes.status()).toBe(200);
      expect(((await vendorRes.json()) as { status: string }).status).toBe("rejected");

      const auditRes = await reviewer.get(`/api/vendors/${vendor.id}/audit`);
      expect(auditRes.status()).toBe(200);
      const audit = (await auditRes.json()) as { items: { action: string }[] };
      expect(audit.items.map((e) => e.action)).toContain("extraction.rejected");
    },
  );
});
